arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *sername*) echo x-access-token ;;
  *) echo "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/askpass.sh && GIT_ASKPASS=/tmp/askpass.sh GIT_TERMINAL_PROMPT=0 git -C /tmp/joey-conv push origin HEAD:refs/heads/friend/joey 2>&1 | tail -3
